""" Returns true if a number is a palindrome """
def is_palindrome(num: Any) -> object {
    (reverse, forward) = (0, num);
    while (num > 0) {
        reverse = (reverse * 10) + (num % 10);
        num /= 10;
    }
    return (forward == reverse);
}

